// VERIFY LIVE: a document-library-backed SharePoint list exposes each
// file as an item with a `driveItem` facet (the underlying Graph
// DriveItem -- id/name/webUrl) alongside the list item's own `id` and
// `fields`. Filter to .xlsx here rather than trusting the library to
// contain only spreadsheets.
return $input.all().filter((item) => (item.json.driveItem?.name ?? '').toLowerCase().endsWith('.xlsx'));

const output = [];
for (const item of $input.all()) {
  const sheet = item.json.data.address.split('!')[0].replace(/^'|'$/g, '');
  const rows = item.json.data.values ?? [];
  for (const row of rows) {
    const dtc = row[0];
    if (!dtc) continue; // skips the leftover sub-header row and blank padding rows within the fixed A3:H5000 range
    output.push({
      json: {
        sheet,
        dtc,
        description: row[1],
        warning_light: row[2],
        warning_message: row[3],
        limp_home: row[4],
        fail_safe: row[5],
        grade: row[6],
        grading_background: row[7],
      },
    });
  }
}
return output;

// REPLACE this object with the current contents of config/sheet_system_mapping.json
// whenever that file changes (rare -- only when sheets are added/renamed).
// Kept as a plain literal here because n8n Cloud can't read files from the git repo.
const MAPPING = {
  /* "SheetName": { "system": "SYS_CODE" }, ... */
};

return $input.all().map((item) => {
  const row = item.json;
  const entry = MAPPING[row.sheet];
  return {
    json: {
      ...row,
      system: entry ? entry.system : "",
    },
  };
});

